// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Keep the domain wide: any new owner other than the zero address.
        vm.assume(newOwner != address(0));

        // The initial owner of c is address(0) (unset owner variable).
        // Only the current owner may call transferOwnership, so the admissible
        // caller here is address(0), the legitimate current owner.
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // General rule: ownership transfer always assigns exactly the requested
        // new owner. The mutant sets owner to address(0) instead, breaking this
        // for every fuzzed newOwner != address(0).
        assertTrue(c.owner() == newOwner);
    }
}
